fn is_ascii_digit(c: char) -> bool {
    // Check if the character is between '0' and '9' inclusive
    c >= '0' && c <= '9'
}

fn all_digits(s: String) -> bool {
    // The empty string vacuously satisfies the condition
    if s.is_empty() {
        return true;
    }
    
    // Check each character in the string
    for c in s.chars() {
        if !is_ascii_digit(c) {
            return false;
        }
    }
    
    true
}